import 'package:flutter/material.dart';import '../models/user.dart';import '../services/api.dart';
class Admin extends StatefulWidget{final User user;final int section;const Admin({super.key,required this.user,required this.section});@override State<Admin> createState()=>_AdminState();}
class _AdminState extends State<Admin>{Map stats={};List users=[],communities=[],posts=[],messages=[];Map config={};bool loading=true;final latest=TextEditingController(),minimum=TextEditingController(),apk=TextEditingController(),poster=TextEditingController(),posterTitle=TextEditingController(),posterMsg=TextEditingController();bool force=false;@override void initState(){super.initState();load();}@override void dispose(){latest.dispose();minimum.dispose();apk.dispose();poster.dispose();posterTitle.dispose();posterMsg.dispose();super.dispose();}Future<void>load()async{setState(()=>loading=true);try{final s=await Api.get('/admin/stats');stats=s['stats']??{};if(widget.section==1)users=List.from((await Api.get('/admin/users'))['users']??[]);if(widget.section==2)communities=List.from((await Api.get('/admin/communities'))['communities']??[]);if(widget.section==3)posts=List.from((await Api.get('/admin/posts'))['posts']??[]);if(widget.section==4)messages=List.from((await Api.get('/admin/messages'))['messages']??[]);if(widget.section==5){final r=await Api.get('/admin/config');config=Map<String,dynamic>.from(r['config']??{});latest.text='${config['latestVersion']??'1.0.0'}';minimum.text='${config['minimumVersion']??'1.0.0'}';apk.text='${config['apkUrl']??''}';poster.text='${config['homePosterUrl']??''}';posterTitle.text='${config['homePosterTitle']??''}';posterMsg.text='${config['homePosterMessage']??''}';force=config['forceUpdate']==true;}}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>loading=false);}}Future<void>saveConfig()async{try{await Api.put('/admin/config',{'latestVersion':latest.text.trim(),'minimumVersion':minimum.text.trim(),'apkUrl':apk.text.trim(),'forceUpdate':force,'updateTitle':'CampusMate update','updateMessage':'A new version is required to continue.','homePosterUrl':poster.text.trim(),'homePosterTitle':posterTitle.text.trim(),'homePosterMessage':posterMsg.text.trim()});if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('App controls saved')));}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}}Future<void>act(String path)async{try{await Api.del(path);load();}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}}Future<void>toggleUser(String id,bool active)async{try{await Api.patch('/admin/users/$id',{'active':active});load();}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}}Future<void>toggleCommunity(String id,bool active)async{try{await Api.patch('/admin/communities/$id',{'active':active});load();}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x'.replaceFirst('Exception: ',''))));}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(widget.section==0)return overview(c);if(widget.section==1)return list(c,'Students',users,(x)=>'${x['name']??''}',(x)=>'${x['email']??''}',(x){final id='${x['_id']}';return Switch(value:x['active']==true,onChanged:(v)=>toggleUser(id,v));},null);if(widget.section==2)return list(c,'Communities',communities,(x)=>'${x['name']??''}',(x)=>'Owner: ${x['owner'] is Map?x['owner']['name']??'':''}',(x){final id='${x['_id']}';return Switch(value:x['active']!=false,onChanged:(v)=>toggleCommunity(id,v));},(x)=>IconButton(onPressed:()=>act('/admin/communities/${x['_id']}'),icon:const Icon(Icons.delete_outline)));if(widget.section==3)return list(c,'Posts',posts,(x)=>'${x['author'] is Map?x['author']['name']??'Student':'Student'}',(x)=>'${x['text']??''}',(_)=>const SizedBox(),(x)=>IconButton(onPressed:()=>act('/admin/posts/${x['_id']}'),icon:const Icon(Icons.delete_outline)));if(widget.section==4)return list(c,'Messages',messages,(x)=>'${x['sender'] is Map?x['sender']['name']??'User':'User'}',(x)=>'${x['text']??''}',(_)=>const SizedBox(),(x)=>IconButton(onPressed:()=>act('/admin/messages/${x['_id']}'),icon:const Icon(Icons.delete_outline)));return update(c);}
Widget overview(BuildContext c)=>ListView(padding:const EdgeInsets.all(18),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(borderRadius:BorderRadius.circular(28),color:const Color(0xFF17172A)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Everything under control.',style:TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.w900)),SizedBox(height:8),Text('Moderate the campus from one place.',style:TextStyle(color:Colors.white70))])),const SizedBox(height:18),Wrap(spacing:12,runSpacing:12,children:stats.entries.map((e)=>SizedBox(width:155,child:Card(child:Padding(padding:const EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${e.value}',style:const TextStyle(fontSize:28,fontWeight:FontWeight.w900)),Text('${e.key}')]))))).toList())]);
Widget list(BuildContext c,String title,List data,String Function(dynamic) a,String Function(dynamic) b,Widget Function(dynamic) trail,Widget Function(dynamic)? action)=>RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text(title,style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:12),...data.map((x)=>Card(child:ListTile(title:Text(a(x),style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(b(x),maxLines:2,overflow:TextOverflow.ellipsis),trailing:Row(mainAxisSize:MainAxisSize.min,children:[trail(x),if(action!=null)action(x)]))))]));
Widget update(BuildContext c)=>ListView(padding:const EdgeInsets.all(18),children:[const Text('Remote app control',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:6),const Text('Change update requirements and the home poster without rebuilding the app.'),const SizedBox(height:18),TextField(controller:latest,decoration:const InputDecoration(labelText:'Latest version')),TextField(controller:minimum,decoration:const InputDecoration(labelText:'Minimum version')),TextField(controller:apk,decoration:const InputDecoration(labelText:'APK URL')),SwitchListTile(value:force,onChanged:(v)=>setState(()=>force=v),title:const Text('Force update')),const Divider(height:30),TextField(controller:poster,decoration:const InputDecoration(labelText:'Home poster image URL')),TextField(controller:posterTitle,decoration:const InputDecoration(labelText:'Poster title')),TextField(controller:posterMsg,decoration:const InputDecoration(labelText:'Poster message')),const SizedBox(height:18),FilledButton.icon(onPressed:saveConfig,icon:const Icon(Icons.save),label:const Text('Save remote controls'))]);}
